$origin = $_SERVER['HTTP_ORIGIN'] ?? '';
if ($origin === 'null') {
    header('Access-Control-Allow-Origin: null');
    header('Vary: Origin');
    header('Access-Control-Allow-Methods: GET, OPTIONS');
    header('Access-Control-Max-Age: 600');
    if (($_SERVER['HTTP_ACCESS_CONTROL_REQUEST_PRIVATE_NETWORK'] ?? '') === 'true') {
        header('Access-Control-Allow-Private-Network: true');
    }
} elseif ($origin === 'http://127.0.0.1:8000' || $origin === 'http://localhost:8000') {
    header('Access-Control-Allow-Origin: ' . $origin);
    header('Vary: Origin');
}
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'OPTIONS') {
    http_response_code(204);
    exit;
}

$period = trim((string)($_GET['period'] ?? ''));
if (!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/', $period)) {
    http_response_code(400);
    header('Content-Type: text/plain; charset=utf-8');
    exit('Periode harus berformat YYYY-MM.');
}
$periodYear = (int)substr($period, 0, 4);
$periodMonth = (int)substr($period, 5, 2);
$monthNames = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
$periodMonthName = strtoupper($monthNames[$periodMonth - 1]);

$conn = new mysqli('127.0.0.1', 'root', '', 'LAPORAN KORPORAT');
if ($conn->connect_error) {
    http_response_code(500);
    header('Content-Type: text/plain; charset=utf-8');
    exit('Database gagal terhubung: ' . $conn->connect_error);
}
$conn->set_charset('utf8mb4');

$stmt = $conn->prepare('SELECT parameter, achievement FROM revenue_selling_in WHERE report_period = ?');
if (!$stmt) {
    http_response_code(500);
    header('Content-Type: text/plain; charset=utf-8');
    exit('Query unduh gagal: ' . $conn->error);
}
$stmt->bind_param('s', $period);
$stmt->execute();
$result = $stmt->get_result();
$amounts = [];
while ($row = $result->fetch_assoc()) $amounts[$row['parameter']] = (float)$row['achievement'];

$lastYearFullPeriod = ($periodYear - 1) . '-12';
$lastYearYtdPeriod = ($periodYear - 1) . '-' . str_pad((string)$periodMonth, 2, '0', STR_PAD_LEFT);
$loadAmounts = static function (mysqli_stmt $statement, string $requestedPeriod): array {
    $statement->bind_param('s', $requestedPeriod);
    $statement->execute();
    $queryResult = $statement->get_result();
    $values = [];
    while ($row = $queryResult->fetch_assoc()) $values[$row['parameter']] = (float)$row['achievement'];
    return $values;
};
$lastYearFullAmounts = $loadAmounts($stmt, $lastYearFullPeriod);
$lastYearYtdAmounts = $loadAmounts($stmt, $lastYearYtdPeriod);
$stmt->close();

// Reuse the UNIT & Revenue upload for the EDP sheet in this server-generated
// workbook. Pick the latest available month up to the requested period.
$edpRecords = [];
$edpSourcePeriod = null;
$previousEdpRecords = [];
$edpColumns = ['rev_jan', 'rev_feb', 'rev_mar', 'rev_apr', 'rev_mei', 'rev_jun', 'rev_jul', 'rev_agt', 'rev_sep', 'rev_okt', 'rev_nov', 'rev_des'];
$candidateMonths = array_merge(range($periodMonth, 1), $periodMonth < 12 ? range($periodMonth + 1, 12) : []);
$edpQuery = $conn->prepare('SELECT report_period, gb, product_name, kategori, rev_jan, rev_feb, rev_mar, rev_apr, rev_mei, rev_jun, rev_jul, rev_agt, rev_sep, rev_okt, rev_nov, rev_des FROM revenue_edp_mnj WHERE report_period = ? ORDER BY id ASC');
if ($edpQuery) {
    foreach ($candidateMonths as $candidateMonth) {
        $candidatePeriod = $periodYear . '-' . str_pad((string)$candidateMonth, 2, '0', STR_PAD_LEFT);
        $edpQuery->bind_param('s', $candidatePeriod);
        $edpQuery->execute();
        $edpResult = $edpQuery->get_result();
        $candidateRecords = $edpResult ? $edpResult->fetch_all(MYSQLI_ASSOC) : [];
        if ($candidateRecords) {
            $edpRecords = $candidateRecords;
            $edpSourcePeriod = $candidatePeriod;
            break;
        }
    }
    $edpQuery->close();
}
// Masa transisi: upload UNIT & Revenue versi lama tersimpan di selling_out.
if (!$edpRecords) {
    $legacyEdpQuery = $conn->prepare('SELECT report_period, gb, product_name, kategori, rev_jan, rev_feb, rev_mar, rev_apr, rev_mei, rev_jun, rev_jul, rev_agt, rev_sep, rev_okt, rev_nov, rev_des FROM revenue_selling_out WHERE report_period = ? ORDER BY id ASC');
    if ($legacyEdpQuery) {
        foreach ($candidateMonths as $candidateMonth) {
            $candidatePeriod = $periodYear . '-' . str_pad((string)$candidateMonth, 2, '0', STR_PAD_LEFT);
            $legacyEdpQuery->bind_param('s', $candidatePeriod);
            $legacyEdpQuery->execute();
            $legacyResult = $legacyEdpQuery->get_result();
            $legacyRecords = $legacyResult ? $legacyResult->fetch_all(MYSQLI_ASSOC) : [];
            if ($legacyRecords) {
                $edpRecords = $legacyRecords;
                $edpSourcePeriod = $candidatePeriod;
                break;
            }
        }
        $legacyEdpQuery->close();
    }
}
// Data tahun sebelumnya juga dipakai untuk mengisi blok REVENUE tahun lalu
// pada sheet EDP, misalnya upload Desember 2025 saat laporan 2026 diunduh.
$previousEdpStart = ($periodYear - 1) . '-01';
$previousEdpEnd = ($periodYear - 1) . '-12';
$previousEdpQuery = $conn->prepare('SELECT report_period, gb, product_name, kategori, rev_jan, rev_feb, rev_mar, rev_apr, rev_mei, rev_jun, rev_jul, rev_agt, rev_sep, rev_okt, rev_nov, rev_des FROM revenue_edp_mnj WHERE report_period >= ? AND report_period <= ? ORDER BY report_period DESC, id ASC');
if ($previousEdpQuery) {
    $previousEdpQuery->bind_param('ss', $previousEdpStart, $previousEdpEnd);
    $previousEdpQuery->execute();
    $previousEdpResult = $previousEdpQuery->get_result();
    $previousEdpPeriod = null;
    while ($previousEdpResult && ($record = $previousEdpResult->fetch_assoc())) {
        if ($previousEdpPeriod === null) $previousEdpPeriod = $record['report_period'];
        if ($record['report_period'] !== $previousEdpPeriod) break;
        $previousEdpRecords[] = $record;
    }
    $previousEdpQuery->close();
}
if (!$previousEdpRecords) {
    $previousLegacyQuery = $conn->prepare('SELECT report_period, gb, product_name, kategori, rev_jan, rev_feb, rev_mar, rev_apr, rev_mei, rev_jun, rev_jul, rev_agt, rev_sep, rev_okt, rev_nov, rev_des FROM revenue_selling_out WHERE report_period >= ? AND report_period <= ? ORDER BY report_period DESC, id ASC');
    if ($previousLegacyQuery) {
        $previousLegacyQuery->bind_param('ss', $previousEdpStart, $previousEdpEnd);
        $previousLegacyQuery->execute();
        $previousLegacyResult = $previousLegacyQuery->get_result();
        $previousLegacyPeriod = null;
        while ($previousLegacyResult && ($record = $previousLegacyResult->fetch_assoc())) {
            if ($previousLegacyPeriod === null) $previousLegacyPeriod = $record['report_period'];
            if ($record['report_period'] !== $previousLegacyPeriod) break;
            $previousEdpRecords[] = $record;
        }
        $previousLegacyQuery->close();
    }
}
