// Jika ada data yang diunggah, pakai kategori A–D atau baris EXIST/NP hasil
// olahan. Kategori raw memiliki prioritas agar tetap bisa dihitung ulang.
$loadTargetMonthlyByCode = static function (mysqli $connection, int $targetYear, array $fallback) : array {
    $monthlyByCode = [];
    $categories = [];
    $finalRows = [];
    $tableCheck = $connection->query("SHOW TABLES LIKE 'target_revenue'");
    if ($tableCheck && $tableCheck->num_rows > 0) {
        $columns = ['januari', 'februari', 'maret', 'april', 'mei', 'juni', 'juli', 'agustus', 'september', 'oktober', 'november', 'desember'];
        $query = $connection->prepare('SELECT product, januari, februari, maret, april, mei, juni, juli, agustus, september, oktober, november, desember FROM target_revenue WHERE product LIKE ? ORDER BY `no`');
        if ($query) {
            $prefix = $targetYear . ' | %';
            $query->bind_param('s', $prefix);
            $query->execute();
            $result = $query->get_result();
            while ($result && ($record = $result->fetch_assoc())) {
                $product = (string)$record['product'];
                $values = array_map(static fn(string $column): float => (float)($record[$column] ?? 0), $columns);
                if (preg_match('/^\d{4} \| GB ([1-6]) \| Kategori ([ABCD])$/u', $product, $match)) {
                    $categories[(int)$match[1]][$match[2]] = $values;
                } elseif (preg_match('/^\d{4} \| GB ([1-6]) \| Existing$/u', $product, $match)) {
                    $finalRows['existing' . $match[1]] = $values;
                } elseif (preg_match('/^\d{4} \| GB ([1-6]) \| New Product$/u', $product, $match)) {
                    $finalRows['new' . $match[1]] = $values;
                }
            }
            $query->close();
        }
    }
    $hasCompleteCategories = true;
    for ($gb = 1; $gb <= 6; $gb++) {
        foreach (['A', 'B', 'C', 'D'] as $category) {
            if (!isset($categories[$gb][$category])) $hasCompleteCategories = false;
        }
    }
    $hasCompleteProcessedRows = true;
    for ($gb = 1; $gb <= 6; $gb++) {
        if (!isset($finalRows['existing' . $gb], $finalRows['new' . $gb])) $hasCompleteProcessedRows = false;
    }
    if ($hasCompleteCategories && $categories) {
        for ($gb = 1; $gb <= 6; $gb++) {
            $monthlyByCode['existing' . $gb] = array_map(static fn(float $a, float $b, float $c): float => $a + $b + $c, $categories[$gb]['A'], $categories[$gb]['B'], $categories[$gb]['C']);
            $monthlyByCode['new' . $gb] = $categories[$gb]['D'];
        }
    } elseif ($hasCompleteProcessedRows && $finalRows) {
        // Processed TARGET SELL OUT uploads already contain the intended
        // EXIST/NP monthly values and should be reused for later periods.
        $monthlyByCode = $finalRows;
    } elseif ($targetYear === 2025 && $fallback) {
        // Keep the supplied processed workbook as a fallback if it has not
        // yet been uploaded through the application.
        $monthlyByCode = $fallback;
    } elseif ($finalRows) {
        $monthlyByCode = $finalRows;
    }
    for ($gb = 1; $gb <= 6; $gb++) {
        $existing = $monthlyByCode['existing' . $gb] ?? null;
        $new = $monthlyByCode['new' . $gb] ?? null;
        if ($existing !== null || $new !== null) {
            $monthlyByCode['gb' . $gb] = array_map(static fn(float $a, float $b): float => $a + $b, $existing ?? array_fill(0, 12, 0.0), $new ?? array_fill(0, 12, 0.0));
        }
    }
    return $monthlyByCode;
};
$targetMonthlyByYear = [];
foreach (array_unique([$periodYear, $periodYear - 1]) as $targetYear) {
    $fallback = $targetYear === 2025 ? $processedTarget2025 : [];
    $targetMonthlyByYear[$targetYear] = $loadTargetMonthlyByCode($conn, $targetYear, $fallback);
}

$output = new Spreadsheet();
$output->getActiveSheet()->setTitle('LAPORAN');
$workbookSheetNames = ['LAPORAN', 'IB', 'ETHICAL', 'MNJ', 'MTM', 'UNIT', 'REVENUE EDP MNJ', 'BIAYA', 'TARGET REVENUE', 'DAFTAR', 'LAUNCH', 'BOD KX Sell In', 'BOD MNJ', 'BOD JML SDM', 'BOD BI.Opr', 'RATIO UPB', 'UP BJ kx', 'UPB non BJ', 'UPB DISTR', 'PARETO UPB DISTR AGT 26', 'complaint - Accident', 'NEAR ED TW 3', 'TOP 10 NEAR ED TW 3'];
$edpTemplateSource = file_get_contents(__DIR__ . '/report-templates.js');
if ($edpTemplateSource === false || !preg_match('/const TEMPLATE_BASE64 = "([A-Za-z0-9+\/=]+)";/', $edpTemplateSource, $edpTemplateMatch)) {
    throw new RuntimeException('Template REVENUE EDP MNJ tertanam tidak ditemukan.');
}
$edpTemplateBytes = base64_decode($edpTemplateMatch[1], true);
$edpTemplatePath = tempnam(sys_get_temp_dir(), 'edp-mnj-template-');
if ($edpTemplateBytes === false || $edpTemplatePath === false || file_put_contents($edpTemplatePath, $edpTemplateBytes) === false) {
    if ($edpTemplatePath !== false) @unlink($edpTemplatePath);
    throw new RuntimeException('Template REVENUE EDP MNJ gagal disiapkan.');
}
try {
    $edpTemplateWorkbook = IOFactory::load($edpTemplatePath);
} finally {
    @unlink($edpTemplatePath);
}
foreach ($workbookSheetNames as $sheetName) {
    if ($sheetName === 'LAPORAN') continue;
    if ($sheetName === 'MTM') {
        $templatePath = tempnam(sys_get_temp_dir(), 'mtm-template-');
        if ($templatePath === false || file_put_contents($templatePath, base64_decode(MTM_TEMPLATE_BASE64, true)) === false) {
            throw new RuntimeException('Template MTM gagal disiapkan.');
        }
        try {
            $mtmWorkbook = IOFactory::load($templatePath);
        } finally {
            @unlink($templatePath);
        }
        $mtmSheet = $mtmWorkbook->getActiveSheet();
        $previousYear = $periodYear - 1;
        $mtmSheet->setCellValue('A1', 'LAMPIRAN : MTM ' . $periodYear);
        $mtmSheet->setCellValue('A3', (string)$periodYear);
        $mtmSheet->setCellValue('C3', $periodMonthName);
        $mtmSheet->setCellValue('A14', 'LAMPIRAN : MTM ' . $previousYear);
        $mtmSheet->setCellValue('A16', (string)$previousYear);
        $mtmSheet->setCellValue('C16', $periodMonthName);
        foreach ([5, 6, 8, 9, 11, 12, 19, 21, 22, 24, 25] as $labelRow) {
            $label = (string)$mtmSheet->getCell('A' . $labelRow)->getValue();
            if (preg_match('/KUM\\s+S\\/D\\s+\\S+/i', $label)) {
                $mtmSheet->setCellValue('A' . $labelRow, preg_replace('/KUM\\s+S\\/D\\s+\\S+/i', 'KUM S/D ' . $periodMonthName, $label));
            }
        }

        // Read MTM values from the file uploaded under the MTM section for this year.
        $loadMtmAmounts = static function (int $sourceYear) use ($conn): array {
            $amounts = [
                'REVENUE' => ['TARGET' => array_fill(0, 12, null), 'ACTUAL' => array_fill(0, 12, null)],
                'EXISTING' => ['TARGET' => array_fill(0, 12, null), 'ACTUAL' => array_fill(0, 12, null)],
                'NEW_PRODUCT' => ['TARGET' => array_fill(0, 12, null), 'ACTUAL' => array_fill(0, 12, null)],
            ];
            $foundData = false;
            $query = $conn->prepare("SELECT report_period, metric_code, value_type, month_number, amount FROM mtm_monthly_values WHERE report_period LIKE CONCAT(?, '-%') ORDER BY report_period DESC, month_number ASC");
            if (!$query) return ['amounts' => $amounts, 'found' => false];
            $yearString = (string)$sourceYear;
            $query->bind_param('s', $yearString);
            if ($query->execute()) {
                $result = $query->get_result();
                $sourcePeriod = null;
                while ($result && ($record = $result->fetch_assoc())) {
                    if ($sourcePeriod === null) $sourcePeriod = $record['report_period'];
                    if ($record['report_period'] !== $sourcePeriod) break;
                    $foundData = true;
                    $metric = strtoupper((string)$record['metric_code']);
                    $type = strtoupper((string)$record['value_type']);
                    $monthIndex = (int)$record['month_number'] - 1;
                    if (!isset($amounts[$metric][$type]) || $monthIndex < 0 || $monthIndex > 11) continue;
                    $amounts[$metric][$type][$monthIndex] = $record['amount'] === null ? null : (float)$record['amount'];
                }
            }
            $query->close();
            return ['amounts' => $amounts, 'found' => $foundData];
        };
        $currentMtmSnapshot = $loadMtmAmounts($periodYear);
        $previousMtmSnapshot = $loadMtmAmounts($periodYear - 1);
        $mtmAmounts = $currentMtmSnapshot['amounts'];
        $previousMtmAmounts = $previousMtmSnapshot['amounts'];
        foreach (['TARGET', 'ACTUAL'] as $valueType) {
            for ($monthIndex = 0; $monthIndex < 12; $monthIndex++) {
                if ($mtmAmounts['REVENUE'][$valueType][$monthIndex] === null) {
                    $existing = $mtmAmounts['EXISTING'][$valueType][$monthIndex];
                    $new = $mtmAmounts['NEW_PRODUCT'][$valueType][$monthIndex];
                    if ($existing !== null || $new !== null) {
                        $mtmAmounts['REVENUE'][$valueType][$monthIndex] = (float)($existing ?? 0) + (float)($new ?? 0);
                    }
                }
            }
        }

        $monthAliases = [
            'JAN' => 0, 'JANUARI' => 0, 'FEB' => 1, 'FEBRUARI' => 1,
            'MAR' => 2, 'MARET' => 2, 'APR' => 3, 'APRIL' => 3,
            'MAY' => 4, 'MEI' => 4, 'JUN' => 5, 'JUNI' => 5,
            'JUL' => 6, 'JULI' => 6, 'AUG' => 7, 'AGS' => 7, 'AGU' => 7, 'AGUSTUS' => 7,
            'SEP' => 8, 'SEPTEMBER' => 8, 'OCT' => 9, 'OKT' => 9, 'OKTOBER' => 9,
            'NOV' => 10, 'NOVEMBER' => 10, 'DEC' => 11, 'DES' => 11, 'DESEMBER' => 11,
        ];
        $monthColumns = [];
        $mtmCellsByRow = [];
        foreach ($mtmSheet->getCellCollection()->getCoordinates() as $coordinate) {
            $value = $mtmSheet->getCell($coordinate)->getValue();
            if ($value === null || $value === '') continue;
            [$columnLetters, $rowNumber] = \PhpOffice\PhpSpreadsheet\Cell\Coordinate::coordinateFromString($coordinate);
            $column = \PhpOffice\PhpSpreadsheet\Cell\Coordinate::columnIndexFromString($columnLetters);
            $mtmCellsByRow[(int)$rowNumber][$column] = $value;
        }
        ksort($mtmCellsByRow);
        foreach ($mtmCellsByRow as $rowNumber => $rowCells) {
            $found = [];
            foreach ($rowCells as $column => $rawValue) {
                $value = strtoupper(trim((string)$rawValue));
                if (isset($monthAliases[$value])) $found[$monthAliases[$value]] = $column;
            }
            if (count($found) === 12) { $monthColumns = $found; break; }
        }
        $sectionOccurrences = [];
        $previousPeriodHeader = null;
        foreach ($mtmCellsByRow as $rowNumber => $rowCells) {
            $rowLabels = array_map(static fn($value): string => strtoupper(trim((string)$value)), array_values($rowCells));
            foreach (['REVENUE', 'EXISTING', 'NEW PRODUCT'] as $label) {
                if (in_array($label, $rowLabels, true)) $sectionOccurrences[] = ['label' => $label, 'row' => $rowNumber];
            }
            if (in_array((string)$previousYear, $rowLabels, true) && in_array('PERIODE', $rowLabels, true) && $rowNumber > 3 && $previousPeriodHeader === null) $previousPeriodHeader = $rowNumber;
        }
        $sumMonthly = static function (array $left, array $right): array {
            $combined = [];
            for ($index = 0; $index < 12; $index++) {
                $combined[$index] = $left[$index] === null && $right[$index] === null
                    ? null
                    : (float)($left[$index] ?? 0) + (float)($right[$index] ?? 0);
            }
            return $combined;
        };
        $buildMetric = static function (array $target, array $actual, bool $isPreviousYear) use ($periodMonth): array {
            $rolling = $actualInPeriod = array_fill(0, 12, null);
            for ($index = 0; $index < 12; $index++) {
                $hasActual = ($isPreviousYear || $index < $periodMonth) && $actual[$index] !== null;
                $rolling[$index] = $hasActual ? (float)($target[$index] ?? 0) : 0;
                if ($hasActual) $actualInPeriod[$index] = (float)$actual[$index];
            }
            $sum = static fn(array $values): float => array_sum(array_map(static fn($value): float => (float)($value ?? 0), $values));
            return [
                'T. AWAL' => $target,
                'T. ROLLING' => $rolling,
                'AKTUAL' => $actualInPeriod,
                'summary' => [
                    'targetTotal' => $sum($target),
                    'targetCum' => $isPreviousYear ? $sum(array_slice($target, 0, $periodMonth)) : $sum($rolling),
                    'actualTotal' => $sum($actualInPeriod),
                    'actualCum' => $sum(array_slice($actualInPeriod, 0, $periodMonth)),
                ],
            ];
        };
        $makeValuesBySection = static function (array $amounts, bool $isPreviousYear) use ($buildMetric, $sumMonthly): array {
            return [
                'REVENUE' => $buildMetric(
                    $sumMonthly($amounts['EXISTING']['TARGET'], $amounts['NEW_PRODUCT']['TARGET']),
                    $sumMonthly($amounts['EXISTING']['ACTUAL'], $amounts['NEW_PRODUCT']['ACTUAL']),
                    $isPreviousYear
                ),
                'EXISTING' => $buildMetric($amounts['EXISTING']['TARGET'], $amounts['EXISTING']['ACTUAL'], $isPreviousYear),
                'NEW PRODUCT' => $buildMetric($amounts['NEW_PRODUCT']['TARGET'], $amounts['NEW_PRODUCT']['ACTUAL'], $isPreviousYear),
            ];
        };
        $writeMtmBlock = static function (array $sections, int $blockEnd, array $valuesBySection, bool $hasData, bool $isPreviousYear) use ($mtmSheet, $mtmCellsByRow, $monthColumns, $periodMonthName): void {
            if (count($sections) !== 3 || count($monthColumns) !== 12) return;
            usort($sections, static fn(array $left, array $right): int => $left['row'] <=> $right['row']);
            foreach ($sections as $sectionIndex => $sectionItem) {
                $sectionLabel = $sectionItem['label'];
                $startRow = $sectionItem['row'];
                $endRow = $sections[$sectionIndex + 1]['row'] ?? $blockEnd;
                if ($sectionIndex === 2 && $isPreviousYear) {
                    for ($row = $startRow; $row < $endRow; $row++) {
                        $labelCell = $mtmSheet->getCell('B' . $row);
                        $label = strtoupper(trim((string)$labelCell->getCalculatedValue() . ' ' . (string)$labelCell->getValue()));
                        if (str_contains($label, 'AKTUAL KUM S/D')) { $endRow = $row + 1; break; }
                    }
                }
                $summaryRows = [];
                for ($rowNumber = $startRow; $rowNumber < $endRow; $rowNumber++) {
                    $labelCell = $mtmSheet->getCell('B' . $rowNumber);
                    $label = strtoupper(trim((string)$labelCell->getCalculatedValue() . ' ' . (string)$labelCell->getValue()));
                    if (str_contains($label, 'TARGET TOTAL')) $summaryRows['targetTotal'] = $rowNumber;
                    elseif (str_contains($label, 'TARGET KUM S/D') || str_contains($label, 'TARGET KUMULATIF')) $summaryRows['targetCum'] = $rowNumber;
                    elseif (str_contains($label, 'AKTUAL TOTAL')) $summaryRows['actualTotal'] = $rowNumber;
                    elseif (str_contains($label, 'AKTUAL KUM S/D')) $summaryRows['actualCum'] = $rowNumber;

                    foreach ($mtmCellsByRow[$rowNumber] ?? [] as $rawValue) {
                        $type = strtoupper(trim((string)$rawValue));
                        if (!isset($valuesBySection[$sectionLabel][$type])) continue;
                        foreach ($monthColumns as $monthIndex => $targetColumn) {
                            $targetCell = \PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($targetColumn) . $rowNumber;
                            $value = $valuesBySection[$sectionLabel][$type][$monthIndex];
                            $mtmSheet->setCellValue($targetCell, $hasData ? $value : null);
                            if ($hasData && $value !== null) $mtmSheet->getStyle($targetCell)->getNumberFormat()->setFormatCode('#,##0');
                        }
                    }
                }
                if (!$isPreviousYear && isset($summaryRows['targetCum'])) $mtmSheet->setCellValue('B' . $summaryRows['targetCum'], 'TARGET KUM S/D ' . $periodMonthName);
                if (isset($summaryRows['actualCum'])) $mtmSheet->setCellValue('B' . $summaryRows['actualCum'], 'AKTUAL KUM S/D ' . $periodMonthName);
                foreach ($summaryRows as $summaryKey => $rowNumber) {
                    $summaryCell = 'C' . $rowNumber;
                    $value = $valuesBySection[$sectionLabel]['summary'][$summaryKey] ?? null;
                    $mtmSheet->setCellValue($summaryCell, $hasData ? $value : null);
                    if ($hasData && $value !== null) $mtmSheet->getStyle($summaryCell)->getNumberFormat()->setFormatCode('#,##0');
                }
            }
        };
        $currentSections = array_values(array_filter($sectionOccurrences, static fn(array $item): bool => $previousPeriodHeader === null || $item['row'] < $previousPeriodHeader));
        $previousSections = array_values(array_filter($sectionOccurrences, static fn(array $item): bool => $previousPeriodHeader !== null && $item['row'] > $previousPeriodHeader));
        $currentValuesBySection = $makeValuesBySection($mtmAmounts, false);
        $previousValuesBySection = $makeValuesBySection($previousMtmAmounts, true);
        $lastTemplateRow = max(array_keys($mtmCellsByRow)) + 1;
        $writeMtmBlock($currentSections, $previousPeriodHeader ?? $lastTemplateRow, $currentValuesBySection, $currentMtmSnapshot['found'], false);
        $writeMtmBlock($previousSections, $lastTemplateRow, $previousValuesBySection, $previousMtmSnapshot['found'], true);
        $mtmSheet->setTitle($sheetName);
        $output->addExternalSheet($mtmSheet);
        continue;
    }
    if ($sheetName === 'REVENUE EDP MNJ') {
        $edpTemplateSheet = $edpTemplateWorkbook->getActiveSheet();
        $previousYear = $periodYear - 1;
        $sectionRows = [
            1 => 'REVENUE TAHUN ' . $periodYear,
            32 => 'TARGET SELL OUT ' . $periodYear,
            59 => 'BIAYA TAHUN ' . $periodYear,
            88 => 'MCM TAHUN ' . $periodYear,
            118 => 'TARGET SELL OUT ' . $previousYear,
            145 => 'REVENUE TAHUN ' . $previousYear,
            176 => 'BIAYA TAHUN ' . $previousYear,
            205 => 'MCM TAHUN ' . $previousYear,
        ];
        foreach ($sectionRows as $row => $label) {
            $edpTemplateSheet->setCellValue('A' . $row, $label);
            $edpTemplateSheet->setCellValue('C' . $row, $periodMonthName);
            $edpTemplateSheet->setCellValue('C' . ($row + 1), 'YTD ' . $periodMonthName);
        }
        // TARGET SELL OUT current year and prior year occupy separate blocks.
        // Both show full-year monthly data; YTD follows the selected period.
        foreach ([[$periodYear, 34], [$previousYear, 120]] as [$targetYear, $firstDataRow]) {
            $targetRows = $targetMonthlyByYear[$targetYear] ?? [];
            for ($gb = 1; $gb <= 6; $gb++) {
                $baseRow = $firstDataRow + (($gb - 1) * 4);
                foreach ([
                    ['existing' . $gb, $baseRow],
                    ['new' . $gb, $baseRow + 1],
                    ['gb' . $gb, $baseRow + 2],
                ] as [$code, $rowNumber]) {
                    if (!isset($targetRows[$code])) continue;
                    $values = $targetRows[$code];
                    for ($monthIndex = 0; $monthIndex < 12; $monthIndex++) {
                        $column = \PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(4 + $monthIndex);
                        $edpTemplateSheet->setCellValue($column . $rowNumber, $values[$monthIndex]);
                    }
                    $edpTemplateSheet->setCellValue('C' . $rowNumber, array_sum(array_slice($values, 0, $periodMonth)));
                    $edpTemplateSheet->setCellValue('P' . $rowNumber, array_sum($values));
                }
            }
        }
        if ($edpRecords && $edpSourcePeriod) {
            $sourceMonth = (int)substr($edpSourcePeriod, 5, 2);
            $sourceMonthName = strtoupper($monthNames[$sourceMonth - 1]);
            $edpTemplateSheet->setCellValue('C1', $sourceMonthName);
            $edpTemplateSheet->setCellValue('C2', 'YTD ' . $sourceMonthName);
            $monthlyByCode = [];
            foreach ($edpRecords as $record) {
                $name = strtoupper(trim((string)($record['product_name'] ?? '')));
                $gb = [];
                preg_match('/^GB\s*(\d+)$/', strtoupper(trim((string)($record['gb'] ?? ''))), $gb);
                $code = null;
                if (preg_match('/^TOTAL\s+GB\s*(\d+)$/', $name, $match)) $code = 'gb' . $match[1];
                elseif (preg_match('/^TOTAL\s+EXISTING\s+GB(?:\s*(\d+))?$/', $name, $match)) $code = 'existing' . ($match[1] ?: ($gb[1] ?? ''));
                elseif (preg_match('/^TOTAL\s+NEW\s+PRODUCT\s+GB(?:\s*(\d+))?$/', $name, $match)) $code = 'new' . ($match[1] ?: ($gb[1] ?? ''));
                elseif (preg_match('/^TOTAL\s+EXISTING\s+GB\s+ET$/', $name)) $code = 'ethicalExisting';
                elseif (preg_match('/^TOTAL\s+NEW\s+PRODUCT\s+GB\s+ET$/', $name)) $code = 'ethicalNew';
                elseif (preg_match('/^TOTAL\s+GB\s+ET$/', $name)) $code = 'ethicalTotal';
                elseif (preg_match('/^(?:TOTAL\s+)?EXIST(?:ING)?\s+ETH$/', $name)) $code = 'ethicalExisting';
                elseif (preg_match('/^(?:TOTAL\s+)?(?:NP|NEW\s+PRODUCT)\s+ETH$/', $name)) $code = 'ethicalNew';
                elseif (preg_match('/^TOTAL\s+ETH$/', $name)) $code = 'ethicalTotal';
                if (!$code) continue;
                $monthlyByCode[$code] ??= array_fill(0, 12, 0.0);
                foreach ($edpColumns as $index => $column) $monthlyByCode[$code][$index] += (float)($record[$column] ?? 0);
            }
            for ($gb = 1; $gb <= 6; $gb++) {
                $existing = $monthlyByCode['existing' . $gb] ?? null;
                $new = $monthlyByCode['new' . $gb] ?? null;
                if ($existing !== null || $new !== null) {
                    $monthlyByCode['gb' . $gb] = array_map(static fn($a, $b): float => $a + $b, $existing ?? array_fill(0, 12, 0.0), $new ?? array_fill(0, 12, 0.0));
                }
            }
            $ethicalExisting = $monthlyByCode['ethicalExisting'] ?? null;
            $ethicalNew = $monthlyByCode['ethicalNew'] ?? null;
            if ($ethicalExisting !== null || $ethicalNew !== null) {
                $monthlyByCode['ethicalTotal'] = array_map(static fn($a, $b): float => $a + $b, $ethicalExisting ?? array_fill(0, 12, 0.0), $ethicalNew ?? array_fill(0, 12, 0.0));
            }
            $templateRows = [];
            for ($gb = 1; $gb <= 6; $gb++) {
                $templateRows['existing' . $gb] = ['EXIST GB ' . $gb, 3 + (($gb - 1) * 4)];
                $templateRows['new' . $gb] = ['NP GB ' . $gb, 4 + (($gb - 1) * 4)];
                $templateRows['gb' . $gb] = ['TOTAL GB ' . $gb, 5 + (($gb - 1) * 4)];
            }
            $templateRows['ethicalExisting'] = ['EXIST ETHICAL', 27];
            $templateRows['ethicalNew'] = ['NP ETHICAL', 28];
            $templateRows['ethicalTotal'] = ['TOTAL ETHICAL', 29];
            foreach ($templateRows as $code => [$label, $rowNumber]) {
                if (!isset($monthlyByCode[$code])) continue;
                $values = $monthlyByCode[$code];
                $ytd = 0.0;
                for ($monthIndex = 0; $monthIndex < 12; $monthIndex++) {
                    $column = \PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(4 + $monthIndex);
                    if ($monthIndex < $sourceMonth) {
                        $edpTemplateSheet->setCellValue($column . $rowNumber, $values[$monthIndex]);
                        $ytd += $values[$monthIndex];
                    } else {
                        $edpTemplateSheet->setCellValue($column . $rowNumber, null);
                    }
                }
                $edpTemplateSheet->setCellValue('C' . $rowNumber, $ytd);
                $edpTemplateSheet->setCellValue('P' . $rowNumber, $ytd);
            }
        }
        if ($previousEdpRecords) {
            $monthlyByCode = [];
            foreach ($previousEdpRecords as $record) {
                $name = strtoupper(trim((string)($record['product_name'] ?? '')));
                $group = strtoupper(trim((string)($record['gb'] ?? '')));
                $code = null;
                if (preg_match('/^TOTAL\s+GB\s*(\d+)$/', $name, $match)) $code = 'gb' . $match[1];
                elseif (preg_match('/^TOTAL\s+EXISTING\s+GB(?:\s*(\d+))?$/', $name, $match)) $code = 'existing' . ($match[1] ?: (preg_match('/^GB\s*(\d+)$/', $group, $gb) ? $gb[1] : ''));
                elseif (preg_match('/^TOTAL\s+NEW\s+PRODUCT\s+GB(?:\s*(\d+))?$/', $name, $match)) $code = 'new' . ($match[1] ?: (preg_match('/^GB\s*(\d+)$/', $group, $gb) ? $gb[1] : ''));
                elseif (preg_match('/^(?:TOTAL\s+)?EXIST(?:ING)?\s+ETH(?:ICAL)?$/', $name)) $code = 'ethicalExisting';
                elseif (preg_match('/^(?:TOTAL\s+)?(?:NP|NEW\s+PRODUCT)\s+ETH(?:ICAL)?$/', $name)) $code = 'ethicalNew';
                elseif (preg_match('/^TOTAL\s+ETH(?:ICAL)?$/', $name)) $code = 'ethicalTotal';
                if (!$code) continue;
                $monthlyByCode[$code] ??= array_fill(0, 12, 0.0);
                foreach ($edpColumns as $index => $column) $monthlyByCode[$code][$index] += (float)($record[$column] ?? 0);
            }
            for ($gb = 1; $gb <= 6; $gb++) {
                $existing = $monthlyByCode['existing' . $gb] ?? null;
                $new = $monthlyByCode['new' . $gb] ?? null;
                if ($existing !== null || $new !== null) {
                    $monthlyByCode['gb' . $gb] = array_map(static fn($a, $b): float => $a + $b, $existing ?? array_fill(0, 12, 0.0), $new ?? array_fill(0, 12, 0.0));
                }
            }
            $ethicalExisting = $monthlyByCode['ethicalExisting'] ?? null;
            $ethicalNew = $monthlyByCode['ethicalNew'] ?? null;
            if ($ethicalExisting !== null || $ethicalNew !== null) {
                $monthlyByCode['ethicalTotal'] = array_map(static fn($a, $b): float => $a + $b, $ethicalExisting ?? array_fill(0, 12, 0.0), $ethicalNew ?? array_fill(0, 12, 0.0));
            }
            $previousRows = [];
            for ($gb = 1; $gb <= 6; $gb++) {
                $base = 147 + (($gb - 1) * 4);
                $previousRows['existing' . $gb] = $base;
                $previousRows['new' . $gb] = $base + 1;
                $previousRows['gb' . $gb] = $base + 2;
            }
            $previousRows['ethicalExisting'] = 171;
            $previousRows['ethicalNew'] = 172;
            $previousRows['ethicalTotal'] = 173;
            foreach ($previousRows as $code => $rowNumber) {
                if (!isset($monthlyByCode[$code])) continue;
                $values = $monthlyByCode[$code];
                $ytd = 0.0;
                for ($monthIndex = 0; $monthIndex < 12; $monthIndex++) {
                    $column = \PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(4 + $monthIndex);
                    $edpTemplateSheet->setCellValue($column . $rowNumber, $values[$monthIndex]);
                    if ($monthIndex < $periodMonth) $ytd += $values[$monthIndex];
                }
                $edpTemplateSheet->setCellValue('C' . $rowNumber, $ytd);
                $edpTemplateSheet->setCellValue('P' . $rowNumber, array_sum($values));
            }
        }
        // Tampilkan angka revenue dengan pemisah ribuan, tetap sebagai nilai numerik.
        $edpTemplateSheet->getStyle('C3:P29')->getNumberFormat()->setFormatCode('#,##0;[Red]-#,##0');
        $edpTemplateSheet->getStyle('C34:P56')->getNumberFormat()->setFormatCode('#,##0;[Red]-#,##0');
        $edpTemplateSheet->getStyle('C120:P142')->getNumberFormat()->setFormatCode('#,##0;[Red]-#,##0');
        $edpTemplateSheet->getStyle('C147:P173')->getNumberFormat()->setFormatCode('#,##0;[Red]-#,##0');
        $edpTemplateSheet->setTitle($sheetName);
        $output->addExternalSheet($edpTemplateSheet);
        continue;
    }
    $output->createSheet()->setTitle($sheetName);
}
$sheet = $output->getSheetByName('BOD KX Sell In');
$sheet->mergeCells('A1:A2');
$sheet->mergeCells('B1:B2');
$sheet->mergeCells('C1:D1');
$sheet->mergeCells('E1:E2');
$sheet->mergeCells('F1:F2');
$sheet->mergeCells('G1:G2');
$sheet->mergeCells('H1:H2');
$sheet->setCellValue('A1', 'No');
$sheet->setCellValue('B1', 'Parameter');
$sheet->setCellValue('C1', 'Ach Last Year (' . ($periodYear - 1) . ')');
$sheet->setCellValue('C2', 'Full Year');
$sheet->setCellValue('D2', 'YTD ' . $periodMonthName);
$sheet->setCellValue('E1', 'Target ' . $periodYear);
$sheet->setCellValue('F1', "Ach " . $periodYear . "\nYTD " . $periodMonthName);
$sheet->setCellValue('G1', "% Achievement\n" . $periodYear);
$sheet->setCellValue('H1', "Growth\nYTD " . $periodMonthName);
$sheet->getStyle('A1:H2')->getFont()->setBold(true);
$sheet->getStyle('A1:H2')->getAlignment()->setHorizontal('center')->setVertical('center')->setWrapText(true);
$sheet->getStyle('A1:H2')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('91C9F7');

$rowNumber = 3;
$resolveAmounts = static function (array $sourceAmounts) use ($definitions): array {
    $sumAmounts = static function (array $parameters) use ($sourceAmounts): float {
        $total = 0.0;
        foreach ($parameters as $parameter) $total += $sourceAmounts[$parameter] ?? 0.0;
        return $total;
    };
    $farmasiTotal = $sumAmounts(['GB 1', 'GB 2', 'GB 3', 'GB 4']);
    $domestikTotal = $farmasiTotal + $sumAmounts(['Biskuit', 'Candy', 'Ethical']);
    $eksporTotal = $sourceAmounts['Ekspor'] ?? $sumAmounts(['IB Farma', 'IB Food']);
    $resolved = [
        'Farmasi' => $farmasiTotal,
        'Domestik' => $domestikTotal,
        'Ekspor' => $eksporTotal,
        'KORPORAT' => $domestikTotal + $eksporTotal,
    ];
    foreach ($definitions as [, $parameter, $children]) {
        $value = $sourceAmounts[$parameter] ?? null;
        if ($parameter === 'Farmasi') {
            $value = $farmasiTotal;
        } elseif ($parameter === 'Domestik') {
            $value = $domestikTotal;
        } elseif ($parameter === 'KORPORAT') {
            $value = $domestikTotal + $eksporTotal;
        } elseif ($value === null && $children) {
            $value = 0.0;
            foreach ($children as $child) $value += $resolved[$child] ?? $sourceAmounts[$child] ?? 0.0;
        }
        if ($value !== null) $resolved[$parameter] = $value;
    }
    return $resolved;
};
$calculatedAmounts = $resolveAmounts($amounts);
$lastYearFullCalculated = $lastYearFullAmounts ? $resolveAmounts($lastYearFullAmounts) : [];
$lastYearYtdCalculated = $lastYearYtdAmounts ? $resolveAmounts($lastYearYtdAmounts) : [];
foreach ($definitions as [$number, $parameter, $children]) {
    $value = $calculatedAmounts[$parameter] ?? null;
    $sheet->setCellValue('A' . $rowNumber, $number);
    $sheet->setCellValue('B' . $rowNumber, $parameter);
    if (array_key_exists($parameter, $lastYearFullCalculated)) $sheet->setCellValue('C' . $rowNumber, $lastYearFullCalculated[$parameter]);
    if (array_key_exists($parameter, $lastYearYtdCalculated)) $sheet->setCellValue('D' . $rowNumber, $lastYearYtdCalculated[$parameter]);
    if ($value !== null) $sheet->setCellValue('F' . $rowNumber, $value);
    if ($value !== null && isset($lastYearYtdCalculated[$parameter]) && $lastYearYtdCalculated[$parameter] != 0.0) {
        $sheet->setCellValue('H' . $rowNumber, '=F' . $rowNumber . '/D' . $rowNumber . '-1');
    }
    if (in_array($parameter, ['KORPORAT', 'Domestik', 'Ekspor'], true)) {
        $sheet->getStyle('A' . $rowNumber . ':H' . $rowNumber)->getFont()->setBold(true);
    }
    $rowNumber++;
}
$lastRow = $rowNumber - 1;
$sheet->getStyle('A1:H' . $lastRow)->getBorders()->getAllBorders()->setBorderStyle(Border::BORDER_THIN);
$sheet->getStyle('C3:H' . $lastRow)->getNumberFormat()->setFormatCode('#,##0;[Red](#,##0);-');
$sheet->getStyle('H3:H' . $lastRow)->getNumberFormat()->setFormatCode('0.00%;[Red](0.00%);-');
$sheet->getStyle('A3:A' . $lastRow)->getAlignment()->setHorizontal('right');
$sheet->getColumnDimension('A')->setWidth(8);
$sheet->getColumnDimension('B')->setWidth(32);
foreach (range('C', 'H') as $column) $sheet->getColumnDimension($column)->setWidth(20);
$sheet->getRowDimension(1)->setRowHeight(28);
$sheet->getRowDimension(2)->setRowHeight(24);
$sheet->freezePane('C3');

// Keep a consistent workbook layout across report downloads. Tabs without
// data for this report remain empty and are ready for their corresponding data.
$conn->close();
$filename = 'Revenue_Konimex_Selling_In_' . str_replace('-', '_', $period) . '.xlsx';
header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
header('Content-Disposition: attachment; filename="' . $filename . '"');
header('Cache-Control: max-age=0, no-cache, no-store, must-revalidate');
(new Xlsx($output))->save('php://output');
